"""Record the actual intro-v2 delivery and preserve prior Drive evidence."""
from pathlib import Path
import json,datetime,hashlib
P=Path(__file__).resolve().parents[2];R=P.parents[1];L=P/'production/local/intro-v2'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 now=datetime.datetime.now(datetime.timezone.utc).isoformat();t=read(P/'production/intro-v2/timing.json');unit=read(P/'production/revisions/intro-v2.json');integrity=read(L/'integrity.json');audio=read(L/'audio-prefix-review.json');delivery=read(P/'production/delivery-output.json')
 assert integrity['status']=='pass' and integrity['body2652DecodedFramesPreserved'] and audio['bodyPcmSampleExact'] and audio['truePeakPass']
 master=next(x for x in delivery['files'] if x['name'].endswith('.captioned.mp4'));assert master['sha256']=='b91f1fce674b6e2426e1a111d8ba1aa45db8e10999fb421871fd711816a61644' and master['bytes']==13676556
 assert sha(R/delivery['directory']/master['name'])==master['sha256']
 proofpath=P/'publishing/drive-playback-intro-v2.json';proof=read(proofpath) if proofpath.exists() else None
 played=bool(proof and proof['fileId']=='1Rf1otHFpSE4rYZH5LOIo8Ty7wsEsY5R4' and proof['ended'] and abs(proof['duration']-t['totalSeconds'])<.1 and proof['width']==1080 and proof['height']==1920)
 receipt=dict(fileId='1Rf1otHFpSE4rYZH5LOIo8Ty7wsEsY5R4',url='https://drive.google.com/file/d/1Rf1otHFpSE4rYZH5LOIo8Ty7wsEsY5R4/view?usp=drivesdk',revisionId='0B__JCPwFbAsxMThIY0RlQzlicnl6Z3Q2b3BMN3JnbGVKZVMwPQ',sourceSha256=master['sha256'],source=delivery['directory']+'/'+master['name'],bytes=13676556,remoteChecksum='not returned; upload-source hash retained and remote byte count matches',access='owner-only; unchanged',metadataReadback=True,uploadCompleted=True,playback='complete1080x1920 observed' if played else 'processing/HD playback pending',playbackEvidence='projects/'+P.name+'/publishing/drive-playback-intro-v2.json' if played else None,humanReview='pending exact intro-v2 version',youtubeUploadAuthorized=False,recordedAt=now,priorFileId=unit['priorDrive']['fileId'])
 save(P/'publishing/drive-receipt.json',receipt)
 review=dict(revision='zombie-quiet-intro-v2',newIntroFrames=277,newIntroSeconds=t['introSeconds'],newMasterSha256=master['sha256'],cleanAndCaptionedFullDecode='pass',regular60FpsPts='pass',retainedBody2652DecodedFramesIdentical=True,retainedBodyMixedPcmSampleIdentical=True,newIntroAsrExactMatch=True,wholeCurrentMixAsr='complete12lines directly compared; intro exact, retained-body lexical variants differ in ASR but unchanged PCM verified',audio=dict(introToOldOpeningSpeechActiveDb=audio['introLevelMatching']['introMinusOldOpeningSpeechActiveDb'],encodedLufs=audio['encodedMeasured']['input_i'],encodedTruePeak=audio['encodedMeasured']['input_tp'],newJoinFlags=audio['reviewFlags']),visual=dict(newCues=2,existingCuesShifted=26,bodyCueShiftFrames=277,newIntroAndJoin='production/local/intro-v2/qa/intro-and-join.jpg',native1080And375px=True,meaning='Same original vector zombie appearance/size; spacing changes, no HP/strength change',bodyReview='reused prior evidence with full decoded-frame equality'),humanListening='pending current full-version review',evidence=['production/local/intro-v2/integrity.json','production/local/intro-v2/audio-prefix-review.json','production/local/intro-v2/asr-intro-71168f19965b.json','production/local/intro-v2/asr-mix-337f92b66ddf.json'])
 save(P/'production/intro-v2/review.json',review)
 ledger=read(P/'production/review-ledger.json');ledger['entries']=[e for e in ledger['entries'] if e.get('revision')!='zombie-quiet-intro-v2']+[dict(kind='selected-intro-revision',revision='zombie-quiet-intro-v2',userEvidence=unit['userEvidence'],result='complete Drive copy; awaiting human review' if played else 'complete master; Drive HD processing',evidence='production/intro-v2/review.json',drive='publishing/drive-receipt.json')];ledger['pending']=['Human final review of exact intro-v2 version, including pronunciation/audio listening','YouTube only after this version approval'];save(P/'production/review-ledger.json',ledger)
 stage='awaiting-human-drive-final-review' if played else 'intro-v2-drive-processing';cp=read(P/'production/checkpoint.json');cp.update(stage=stage,currentRevision='zombie-quiet-intro-v2',currentMasterSha256=master['sha256'],driveId=receipt['fileId'],humanFinalReview='pending new48.8167sec version',next='Wait for human review; no next video',nextAction='Wait for human review' if played else 'Verify Drive HD playback',youtubeUploaded=False);cp['introRevision']=dict(voiceSeconds=4.16,frames=277,bodySeconds=44.2,bodyPcmRetained=True,bodyDecodedFramesIdentical=True);save(P/'production/checkpoint.json',cp)
 project=read(P/'project.json');project.update(status=stage,driveFinalReview=receipt,publishReady=False);project['finalRender'].update(durationSeconds=t['totalSeconds'],captionedSha256=master['sha256'],complete=True);save(P/'project.json',project)
 plan=read(P/'planning/production-plan.json');plan.update(status=stage,humanFinalReview='pending exact intro-v2 Drive version');plan['latestRevision']=dict(**unit,status=stage,review='production/intro-v2/review.json',drive=receipt);save(P/'planning/production-plan.json',plan)
 publishing=read(P/'publishing/plan.json');publishing.update(driveFinalReview=receipt,previousDriveFinalReview=unit['priorDrive'],durationSeconds=t['totalSeconds'],masterSha256=master['sha256'],humanApproval='pending exact intro-v2',youtubeId=None)
 for lang in ['ko','en']:
  desc=(P/f'publishing/description.{lang}.txt').read_text(encoding='utf8');oldcredits=publishing['sourceCredits'][lang];marker=oldcredits.splitlines()[0];assert marker in desc;publishing['sourceCredits'][lang]=desc[desc.index(marker):].rstrip()
 save(P/'publishing/plan.json',publishing)
 controlpath=R/'shared/publishing/video-production-control.json';control=read(controlpath);selected=control['shortsRecurringAuthorization'];assert selected['selectedShort']==P.name and selected['latestSelection']['selectedRevision']=='zombie-quiet-intro-v2';selected['latestSelection'].update(productionStatus=stage,driveFinalReview=receipt,humanReview='pending this revised version');save(controlpath,control)
 workpath=R/'shared/publishing/shorts-worklist.json';work=read(workpath);row=next(x for x in work['rows'] if x['slug']==P.name);row.update(productionStatus='complete48.8167secFHD60;4.6167secintro added',reviewStatus='awaiting final user review' if played else 'Drive HD processing',userApproval='pending intro-v2 exact version',driveId=receipt['fileId'],driveFinalReview=receipt,currentRevision='zombie-quiet-intro-v2',durationSeconds=t['totalSeconds'],status=stage,activeReviewSlot=True);work.update(updatedAt=now,latestUserSteering=selected['latestSelection']);save(workpath,work)
 print(json.dumps(dict(stage=stage,drive=receipt['fileId'],sha256=master['sha256'],seconds=t['totalSeconds'])))
if __name__=='__main__':main()
